<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { message } from 'ant-design-vue'
import { get, post, put } from '../api'
interface UserRow { id:number;username:string;displayName:string;role:string;enabled:boolean }
interface RoleOption { label:string; value:string }
const rows=ref<UserRow[]>([]);const roles=ref<RoleOption[]>([]);const loading=ref(false);const modalOpen=ref(false);const passwordOpen=ref(false);const editing=ref<UserRow|null>(null);const form=reactive({username:'',displayName:'',password:'',role:'OPERATOR',enabled:true});const password=ref('')
async function load(){loading.value=true;try{[rows.value,roles.value]=await Promise.all([get<UserRow[]>('/auth/users'),get<RoleOption[]>('/auth/users/roles')])}finally{loading.value=false}}
function openCreate(){editing.value=null;Object.assign(form,{username:'',displayName:'',password:'',role:'OPERATOR',enabled:true});modalOpen.value=true}
function openEdit(row:UserRow){editing.value=row;Object.assign(form,{username:row.username,displayName:row.displayName,password:'',role:row.role,enabled:row.enabled});modalOpen.value=true}
async function save(){if(editing.value)await put(`/auth/users/${editing.value.id}`,{displayName:form.displayName,role:form.role,enabled:form.enabled});else await post('/auth/users',{username:form.username,displayName:form.displayName,password:form.password,role:form.role});message.success(editing.value?'成员已更新':'成员已创建');modalOpen.value=false;load()}
function openPassword(row:UserRow){editing.value=row;password.value='';passwordOpen.value=true}
async function resetPassword(){if(!editing.value)return;await put(`/auth/users/${editing.value.id}/password`,{password:password.value});message.success('密码已重置');passwordOpen.value=false}
onMounted(load)
</script>
<template><div class="page-container"><div class="page-heading"><div><span class="eyebrow blue">Tenant members</span><h1>成员与角色</h1><p>角色权限由服务端统一维护，用户停用后无法登录。</p></div><a-button type="primary" size="large" @click="openCreate">创建成员</a-button></div><div class="table-card"><a-table :data-source="rows" :loading="loading" row-key="id"><a-table-column title="ID" data-index="id" width="80" /><a-table-column title="用户名" data-index="username" /><a-table-column title="显示名称" data-index="displayName" /><a-table-column title="角色" data-index="role" /><a-table-column title="状态" key="enabled"><template #default="{record}"><a-badge :status="record.enabled?'success':'default'" :text="record.enabled?'已启用':'已停用'" /></template></a-table-column><a-table-column title="操作" key="actions"><template #default="{record}"><a-button type="link" @click="openEdit(record)">编辑</a-button><a-button type="link" @click="openPassword(record)">重置密码</a-button></template></a-table-column></a-table></div><a-modal v-model:open="modalOpen" :title="editing?'编辑成员':'创建成员'" @ok="save"><a-form layout="vertical"><a-form-item label="用户名"><a-input v-model:value="form.username" :disabled="Boolean(editing)" /></a-form-item><a-form-item label="显示名称"><a-input v-model:value="form.displayName" /></a-form-item><a-form-item v-if="!editing" label="初始密码"><a-input-password v-model:value="form.password" minlength="8" /></a-form-item><a-form-item label="角色"><a-select v-model:value="form.role" :options="roles" /></a-form-item><a-form-item v-if="editing" label="启用"><a-switch v-model:checked="form.enabled" /></a-form-item></a-form></a-modal><a-modal v-model:open="passwordOpen" title="重置密码" @ok="resetPassword"><a-input-password v-model:value="password" placeholder="请输入 8-72 位新密码" minlength="8" /></a-modal></div></template>
